#!/usr/bin/env python3
"""
Round nh4 (culprits), 17 October 2026, from the Invasion of non-humans chat.
Needs round nh3.

The six "How the countries are governed" rows shade by the World Bank's new
governance score (0 to 100) instead of the withdrawn percentile rank. Changes
map/app.js and map/test.mjs only.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round nh4 (17 October, the Invasion of non-humans chat)\n\nNeeds round nh3 (guards on its heading).\n\n- The six governance rows (wgi_*) were empty: the World Bank withdrew the WGI percentile-rank\n  series (GE.PER.RNK and the rest) in its September 2025 revision. They now shade by the new\n  governance score, 0 (worst) to 100 (best), field <key>_score in nonhuman/wgi.json (tiles\n  nonhuman_wgi.py reads GOV_WGI_*.SC, its bounds and the estimate). Names, units and notes say so.\n']

DIFF = ''


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("nonhuman4: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round nh3" not in h.read_text(encoding="utf-8"):
        sys.exit("nonhuman4: round nh3 must be applied first (nonhuman3_culprits.py)")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("nonhuman4: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("nonhuman4: the diff did not apply:\n" + r.stdout + r.stderr)
        print("nonhuman4: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
